// Train Hitpoints by attacking rats continuously
async function trainHitpoints() {
  while (true) {
    try {
      // Find and attack nearest rat
      const state = sdk.getState();
      const rats = state.npcs.filter(npc => npc.name.toLowerCase().includes('rat'));
      if (rats.length > 0) {
        // Sort by distance and attack the closest one
        rats.sort((a, b) => a.distance - b.distance);
        await bot.attackNpc(rats[0].name);
      } else {
        console.log('No rats nearby, waiting...');
        await new Promise(resolve => setTimeout(resolve, 1000));
      }
    } catch (error) {
      console.log('Error during training:', error);
      await new Promise(resolve => setTimeout(resolve, 1000));
    }
  }
}

