// Ranged training script for AI benchmarking
import { BotActions, BotSDK } from '/app/benchmark/shared/types';

async function trainRanged(bot: BotActions, sdk: BotSDK) {
  // Equip ranged gear
  await bot.equipItem("Shortbow");
  await bot.equipItem("Bronze arrow");

  while (true) {
    // Find nearest rat
    const nearbyNpcs = sdk.getNearbyNpcs();
    const rat = nearbyNpcs.find(npc => npc.name === "Rat");

    if (rat) {
      try {
        await bot.attackNpc("Rat");
        // Wait a bit between attacks to avoid spamming
        await new Promise(resolve => setTimeout(resolve, 1000));
      } catch (error) {
        console.log("Error attacking rat:", error);
        await new Promise(resolve => setTimeout(resolve, 2000));
      }
