async function trainCooking() {
  console.log("Starting cooking training loop...");

  while (true) {
    try {
      // Check if we have raw fish to cook
      const inventory = sdk.getInventory();
      const rawFish = inventory.find(item => /raw.*shrimp|raw.*fish/i.test(item.name));

